 * one independent state per key, created lazily the first time a key
 * reaches the policy.
 */

/**
 * A token bucket holding `capacity` tokens, refilling `refill` tokens for
 * every `per` ticks that pass. Tokens are tracked as a numerator over
 * `per` so that partial refills accumulate exactly, without floating
 * point rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityNumerator = capacity * per
    this.keys = new Map()
  }

  #stateFor(key, tick) {
    let state = this.keys.get(key)
    if (state === undefined) {
      state = { tokensNumerator: this.capacityNumerator, lastTick: tick }
      this.keys.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.tokensNumerator += this.refill * elapsed
      if (state.tokensNumerator > this.capacityNumerator) {
        state.tokensNumerator = this.capacityNumerator
      }
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.keys.get(key)
    return state.tokensNumerator >= this.per
  }

  record(key) {
    const state = this.keys.get(key)
    state.tokensNumerator -= this.per
  }
}

/**
 * A sliding window remembering the ticks of the requests it recorded for
 * a key, forgetting any tick at or before `tick - span` on each advance.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.keys = new Map()
  }

  #stateFor(key) {
    let state = this.keys.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.keys.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) {
      cut++
    }
    if (cut > 0) {
      state.ticks.splice(0, cut)
    }
  }

  allow(key) {
    const state = this.keys.get(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key) {
    const state = this.keys.get(key)
    // The tick that provoked this record is always the most recent one
    // advance() was called with, so it belongs at the end.
    state.ticks.push(state.ticks.length > 0 ? state.ticks[state.ticks.length - 1] : undefined)
  }
}
