{"file_path":"src/parse.js","content":"/**
 * Parses a limiter file into declared policies, routes and an ordered
 * list of events, enforcing every rule the format imposes. Throws a
 * `ParseError` carrying the offending line number on the first problem
 * found; callers should stop at that point.
 */
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function parseIntField(line, str, field, min) {
  if (!INT_RE.test(str)) {
    fail(line, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(str)
  if (value < min) {
    fail(line, `${field} must be an integer of at least ${min}`)
  }
  return value
}

/**
 * Parses the full text of a limiter file.
 * @returns {{policies: Map<string, object>, routes: Array<{prefix: string, policyNames: string[]}>, events: Array<{tick: bigint, key: string}>}}
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (rest.length !== 4) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityStr, refillStr, perStr] = rest
      if (!NAME_RE.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseIntField(lineNo, capacityStr, 'capacity', 1n)
      const refill = parseIntField(lineNo, refillStr, 'refill', 0n)
      const per = parseIntField(lineNo, perStr, 'per', 1n)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (rest.length !== 3) fail(lineNo, 'expected window <name> <limit> <span>')
      const [name, limitStr, spanStr] = rest
      if (!NAME_RE.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseIntField(lineNo, limitStr, 'limit', 0n)
      const span = parseIntField(lineNo, spanStr, 'span', 1n)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (rest.length < 2) fail(lineNo, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!NAME_RE.test(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routesByPrefix.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(lineNo, `unknown policy ${name}`)
      }
      const route = { prefix, policyNames }
      routes.push(route)
      routesByPrefix.set(prefix, route)
    } else if (directive === 'event') {
      seenEvent = true
      if (rest.length !== 2) fail(lineNo, 'expected event <tick> <key>')
      const [tickStr, key] = rest
      const tick = parseIntField(lineNo, tickStr, 'tick', 0n)
      if (!NAME_RE.test(key)) fail(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

