{"file_path":"src/simulate.js","content":"/**
 * Replays parsed events against their routed policies, producing either
 * a per-event verdict log or a per-key summary.
 */

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) {
        best = route
      }
    }
  }
  return best
}

/**
 * @returns {Array<{tick: bigint, key: string, allowed: boolean, deniedBy: string|null}>}
 */
export function simulate(parsed) {
  const { policies, routes, events } = parsed
  const verdicts = []

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    if (route === null) {
      verdicts.push({ tick, key, allowed: true, deniedBy: null })
      continue
    }

    for (const name of route.policyNames) {
      policies.get(name).advance(key, tick)
    }

    let deniedBy = null
    for (const name of route.policyNames) {
      if (!policies.get(name).allow(key)) {
        deniedBy = name
        break
      }
    }

    if (deniedBy === null) {
      for (const name of route.policyNames) {
        policies.get(name).record(key)
      }
      verdicts.push({ tick, key, allowed: true, deniedBy: null })
    } else {
      verdicts.push({ tick, key, allowed: false, deniedBy })
    }
  }

  return verdicts
}

export function formatReplay(verdicts) {
  const lines = []
  for (const v of verdicts) {
    if (v.allowed) {
      lines.push(`${v.tick} ${v.key} allow`)
    } else {
      lines.push(`${v.tick} ${v.key} deny ${v.deniedBy}`)
    }
  }
  return lines.map((line) => line + '\n').join('')
}

export function formatSummary(verdicts) {
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const v of verdicts) {
    let stats = perKey.get(v.key)
    if (stats === undefined) {
      stats = { allowed: 0n, denied: 0n }
      perKey.set(v.key, stats)
    }
    if (v.allowed) {
      stats.allowed++
      totalAllowed++
    } else {
      stats.denied++
      totalDenied++
    }
  }

  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const stats = perKey.get(key)
    return `${key} allowed=${stats.allowed} denied=${stats.denied}\n`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}
"}

