 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parseLimiterFile, ParseError } from './parse.js'
import { simulate, formatReplay, formatSummary } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  const verdicts = simulate(parsed)
  const output = mode === 'replay' ? formatReplay(verdicts) : formatSummary(verdicts)
  process.stdout.write(output)
  process.exit(0)
}

